 "mainEntity": [
  {
   "@type": "Question",
   "name": "진돗개는 왜 집에서 배변을 안 하나요?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "자는 곳을 깨끗하게 지키려는 성향이 강하고, 한 번 익힌 \"배변은 밖\" 규칙을 잘 바꾸지 않기 때문이라고 알려져 있어요. 냄새로 영역을 확인하는 습성도 한몫해요."
   }
  },
  {
   "@type": "Question",
   "name": "진돗개도 실내배변 훈련이 되나요?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "되는 아이도 있지만 끝내 패드를 안 쓰는 아이도 많아요. 현관이나 베란다에 인조잔디를 두고 산책 때 묻힌 냄새로 유도해 보되, 안 되면 산책 횟수를 넉넉히 하는 쪽이 현실적이에요."
   }
  },
  {
   "@type": "Question",
   "name": "진도믹스도 실외배변을 고집하나요?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "진도 성향이 강하게 나온 진도믹스는 실외배변을 고집하는 경우가 많아요. 입양 전 지내던 곳에서 흙이나 풀 위에서 싸는 습관이 든 아이도 있어요."
   }
  },
  {
   "@type": "Question",
   "name": "실외배변 진돗개는 하루 몇 번 나가야 하나요?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "성견은 하루 3~4번 배변 기회를 주라고 흔히 권해요. 최소한 아침과 자기 전 두 번은 꼭 나가고, 8시간 넘게 기회가 없는 날이 이어지지 않게 해 주세요."
   }
  }
 ]
